16	package retrofit2;
17	
18	import static retrofit2.Utils.getRawType;
19	import static retrofit2.Utils.methodError;
20	
21	import java.lang.annotation.Annotation;
22	import java.lang.reflect.Method;
23	import java.lang.reflect.ParameterizedType;
24	import java.lang.reflect.Type;
25	import javax.annotation.Nullable;
26	import kotlin.Unit;
27	import kotlin.coroutines.Continuation;
28	import okhttp3.ResponseBody;
29	
30	/** Adapts an invocation of an interface method into an HTTP call. */
31	abstract class HttpServiceMethod<ResponseT, ReturnT> extends ServiceMethod<ReturnT> {
32	  /**
33	   * Inspects the annotations on an interface method to construct a reusable service method that
34	   * speaks HTTP. This requires potentially-expensive reflection so it is best to build each service
35	   * method only once and reuse it.
36	   */
37	  static <ResponseT, ReturnT> HttpServiceMethod<ResponseT, ReturnT> parseAnnotations(
38	      Retrofit retrofit, Method method, RequestFactory requestFactory) {
39	    boolean isKotlinSuspendFunction = requestFactory.isKotlinSuspendFunction;
40	    boolean continuationWantsResponse = false;
41	    boolean continuationBodyNullable = false;
42	    boolean continuationIsUnit = false;
43	
44	    Annotation[] annotations = method.getAnnotations();
45	    Type adapterType;
46	    if (isKotlinSuspendFunction) {
47	      Type[] parameterTypes = method.getGenericParameterTypes();
48	      Type responseType =
49	          Utils.getParameterLowerBound(
50	              0, (ParameterizedType) parameterTypes[parameterTypes.length - 1]);
51	      if (getRawType(responseType) == Response.class && responseType instanceof ParameterizedType) {
52	        // Unwrap the actual body type from Response<T>.
53	        responseType = Utils.getParameterUpperBound(0, (ParameterizedType) responseType);
54	        continuationWantsResponse = true;
55	      } else {
56	        if (getRawType(responseType) == Call.class) {
57	          throw methodError(
58	              method,
59	              "Suspend functions should not return Call, as they already execute asynchronously.\n"
60	                  + "Change its return type to %s",
61	              Utils.getParameterUpperBound(0, (ParameterizedType) responseType));
62	        }
63	
64	        continuationIsUnit = Utils.isUnit(responseType);
65	        // TODO figure out if type is nullable or not
66	        // Metadata metadata = method.getDeclaringClass().getAnnotation(Metadata.class)
67	        // Find the entry for method
68	        // Determine if return type is nullable or not
69	      }
70	
71	      adapterType = new Utils.ParameterizedTypeImpl(null, Call.class, responseType);
72	      annotations = SkipCallbackExecutorImpl.ensurePresent(annotations);
73	    } else {
74	      adapterType = method.getGenericReturnType();
75	    }
76	
77	    CallAdapter<ResponseT, ReturnT> callAdapter =
78	        createCallAdapter(retrofit, method, adapterType, annotations);
79	    Type responseType = callAdapter.responseType();
80	    if (responseType == okhttp3.Response.class) {
81	      throw methodError(
82	          method,
83	          "'"
84	              + getRawType(responseType).getName()
85	              + "' is not a valid response body type. Did you mean ResponseBody?");
86	    }
87	    if (responseType == Response.class) {
88	      throw methodError(method, "Response must include generic type (e.g., Response<String>)");
89	    }
90	    if (requestFactory.httpMethod.equals("HEAD")
91	        && !Void.class.equals(responseType)
92	        && !Utils.isUnit(responseType)) {
93	      throw methodError(method, "HEAD method must use Void or Unit as response type.");
94	    }
95	
96	    Converter<ResponseBody, ResponseT> responseConverter =
97	        createResponseConverter(retrofit, method, responseType);
98	
99	    okhttp3.Call.Factory callFactory = retrofit.callFactory;
100	    if (!isKotlinSuspendFunction) {
101	      return new CallAdapted<>(requestFactory, callFactory, responseConverter, callAdapter);
102	    } else if (continuationWantsResponse) {
103	      //noinspection unchecked Kotlin compiler guarantees ReturnT to be Object.
104	      return (HttpServiceMethod<ResponseT, ReturnT>)
105	          new SuspendForResponse<>(
106	              requestFactory,
107	              callFactory,
108	              responseConverter,
109	              (CallAdapter<ResponseT, Call<ResponseT>>) callAdapter);
110	    } else {
111	      //noinspection unchecked Kotlin compiler guarantees ReturnT to be Object.
112	      return (HttpServiceMethod<ResponseT, ReturnT>)
113	          new SuspendForBody<>(
114	              requestFactory,
115	              callFactory,
116	              responseConverter,
117	              (CallAdapter<ResponseT, Call<ResponseT>>) callAdapter,
118	              continuationBodyNullable,
119	              continuationIsUnit);
120	    }
121	  }
122	
123	  private static <ResponseT, ReturnT> CallAdapter<ResponseT, ReturnT> createCallAdapter(
124	      Retrofit retrofit, Method method, Type returnType, Annotation[] annotations) {
125	    try {
126	      //noinspection unchecked
127	      return (CallAdapter<ResponseT, ReturnT>) retrofit.callAdapter(returnType, annotations);
