45	/**
46	 * Retrofit adapts a Java interface to HTTP calls by using annotations on the declared methods to
47	 * define how requests are made. Create instances using {@linkplain Builder the builder} and pass
48	 * your interface to {@link #create} to generate an implementation.
49	 *
50	 * <p>For example,
51	 *
52	 * <pre><code>
53	 * Retrofit retrofit = new Retrofit.Builder()
54	 *     .baseUrl("https://api.example.com/")
55	 *     .addConverterFactory(GsonConverterFactory.create())
56	 *     .build();
57	 *
58	 * MyApi api = retrofit.create(MyApi.class);
59	 * Response&lt;User&gt; user = api.getUser().execute();
60	 * </code></pre>
61	 *
62	 * @author Bob Lee (bob@squareup.com)
63	 * @author Jake Wharton (jw@squareup.com)
64	 */
65	public final class Retrofit {
66	  /**
67	   * Method associations in this map will be in one of three states, and may only progress forward
68	   * to higher-numbered states.
69	   * <ol>
70	   *   <li>No value - no one has started or completed parsing annotations for the method.</li>
71	   *   <li>Lock object - a thread has started parsing annotations on the method. Once the lock is
72	   *   available the map will have been updated with the parsed model.</li>
73	   *   <li>{@code ServiceMethod} - annotations for the method have been fully parsed.</li>
74	   * </ol>
75	   * This map should only be accessed through {@link #loadServiceMethod} which contains the state
76	   * transition logic.
77	   */
78	  private final ConcurrentHashMap<Method, Object> serviceMethodCache = new ConcurrentHashMap<>();
79	
80	  final okhttp3.Call.Factory callFactory;
81	  final HttpUrl baseUrl;
82	  final List<Converter.Factory> converterFactories;
83	  final int defaultConverterFactoriesSize;
84	  final List<CallAdapter.Factory> callAdapterFactories;
85	  final int defaultCallAdapterFactoriesSize;
86	  final @Nullable Executor callbackExecutor;
87	  final boolean validateEagerly;
88	
89	  Retrofit(
90	      okhttp3.Call.Factory callFactory,
91	      HttpUrl baseUrl,
92	      List<Converter.Factory> converterFactories,
93	      int defaultConverterFactoriesSize,
94	      List<CallAdapter.Factory> callAdapterFactories,
95	      int defaultCallAdapterFactoriesSize,
96	      @Nullable Executor callbackExecutor,
97	      boolean validateEagerly) {
98	    this.callFactory = callFactory;
99	    this.baseUrl = baseUrl;
100	    this.converterFactories = converterFactories; // Copy+unmodifiable at call site.
101	    this.defaultConverterFactoriesSize = defaultConverterFactoriesSize;
102	    this.callAdapterFactories = callAdapterFactories; // Copy+unmodifiable at call site.
103	    this.defaultCallAdapterFactoriesSize = defaultCallAdapterFactoriesSize;
104	    this.callbackExecutor = callbackExecutor;
105	    this.validateEagerly = validateEagerly;
106	  }
107	
108	  /**
109	   * Create an implementation of the API endpoints defined by the {@code service} interface.
110	   *
111	   * <p>The relative path for a given method is obtained from an annotation on the method describing
112	   * the request type. The built-in methods are {@link retrofit2.http.GET GET}, {@link
113	   * retrofit2.http.PUT PUT}, {@link retrofit2.http.POST POST}, {@link retrofit2.http.PATCH PATCH},
114	   * {@link retrofit2.http.HEAD HEAD}, {@link retrofit2.http.DELETE DELETE},
115	   * {@link retrofit2.http.OPTIONS OPTIONS}, and {@link retrofit2.http.QUERY QUERY}.
116	   * You can use a custom HTTP method with {@link HTTP @HTTP}. For
117	   * a dynamic URL, omit the path on the annotation and annotate the first parameter with {@link
118	   * Url @Url}.
119	   *
120	   * <p>Method parameters can be used to replace parts of the URL by annotating them with {@link
121	   * retrofit2.http.Path @Path}. Replacement sections are denoted by an identifier surrounded by
122	   * curly braces (e.g., "{foo}"). To add items to the query string of a URL use {@link
123	   * retrofit2.http.Query @Query}.
124	   *
125	   * <p>The body of a request is denoted by the {@link retrofit2.http.Body @Body} annotation. The
126	   * object will be converted to request representation by one of the {@link Converter.Factory}
127	   * instances. A {@link RequestBody} can also be used for a raw representation.
128	   *
129	   * <p>Alternative request body formats are supported by method annotations and corresponding
130	   * parameter annotations:
131	   *
132	   * <ul>
133	   *   <li>{@link retrofit2.http.FormUrlEncoded @FormUrlEncoded} - Form-encoded data with key-value
134	   *       pairs specified by the {@link retrofit2.http.Field @Field} parameter annotation.
135	   *   <li>{@link retrofit2.http.Multipart @Multipart} - RFC 2388-compliant multipart data with
136	   *       parts specified by the {@link retrofit2.http.Part @Part} parameter annotation.
137	   * </ul>
138	   *
139	   * <p>Additional static headers can be added for an endpoint using the {@link
140	   * retrofit2.http.Headers @Headers} method annotation. For per-request control over a header
141	   * annotate a parameter with {@link Header @Header}.
142	   *
143	   * <p>By default, methods return a {@link Call} which represents the HTTP request. The generic
144	   * parameter of the call is the response body type and will be converted by one of the {@link
145	   * Converter.Factory} instances. {@link ResponseBody} can also be used for a raw representation.
146	   * {@link Void} can be used if you do not care about the body contents.
147	   *
148	   * <p>For example:
149	   *
150	   * <pre>
151	   * public interface CategoryService {
152	   *   &#64;POST("category/{cat}/")
153	   *   Call&lt;List&lt;Item&gt;&gt; categoryList(@Path("cat") String a, @Query("page") int b);
154	   * }
155	   * </pre>
156	   */
157	  @SuppressWarnings("unchecked") // Single-interface proxy creation guarded by parameter safety.
158	  public <T> T create(final Class<T> service) {
159	    validateServiceInterface(service);
160	    return (T)
161	        Proxy.newProxyInstance(
162	            service.getClassLoader(),
163	            new Class<?>[] {service},
164	            new InvocationHandler() {
165	              private final Object[] emptyArgs = new Object[0];
166	
167	              @Override
168	              public @Nullable Object invoke(Object proxy, Method method, @Nullable Object[] args)
169	                  throws Throwable {
170	                // If the method is a method from Object then defer to normal invocation.
171	                if (method.getDeclaringClass() == Object.class) {
172	                  return method.invoke(this, args);
173	                }
174	                args = args != null ? args : emptyArgs;
175	                Reflection reflection = Platform.reflection;
176	                return reflection.isDefaultMethod(method)
177	                    ? reflection.invokeDefaultMethod(method, service, proxy, args)
178	                    : loadServiceMethod(service, method).invoke(proxy, args);
179	              }
180	            });
