183	  private void validateServiceInterface(Class<?> service) {
184	    if (!service.isInterface()) {
185	      throw new IllegalArgumentException("API declarations must be interfaces.");
186	    }
187	
188	    Deque<Class<?>> check = new ArrayDeque<>(1);
189	    check.add(service);
190	    while (!check.isEmpty()) {
191	      Class<?> candidate = check.removeFirst();
192	      if (candidate.getTypeParameters().length != 0) {
193	        StringBuilder message =
194	            new StringBuilder("Type parameters are unsupported on ").append(candidate.getName());
195	        if (candidate != service) {
196	          message.append(" which is an interface of ").append(service.getName());
197	        }
198	        throw new IllegalArgumentException(message.toString());
199	      }
200	      Collections.addAll(check, candidate.getInterfaces());
201	    }
202	
203	    if (validateEagerly) {
204	      Reflection reflection = Platform.reflection;
205	      for (Method method : service.getDeclaredMethods()) {
206	        if (!reflection.isDefaultMethod(method)
207	            && !Modifier.isStatic(method.getModifiers())
208	            && !method.isSynthetic()) {
209	          loadServiceMethod(service, method);
210	        }
211	      }
212	    }
213	  }
