279	  /**
280	   * Returns a list of the factories tried when creating a {@linkplain #callAdapter(Type,
281	   * Annotation[])} call adapter}.
282	   */
283	  public List<CallAdapter.Factory> callAdapterFactories() {
284	    return callAdapterFactories;
285	  }
