287	  /**
288	   * Returns the {@link CallAdapter} for {@code returnType} from the available {@linkplain
289	   * #callAdapterFactories() factories}.
290	   *
291	   * @throws IllegalArgumentException if no call adapter available for {@code type}.
292	   */
293	  public CallAdapter<?, ?> callAdapter(Type returnType, Annotation[] annotations) {
294	    return nextCallAdapter(null, returnType, annotations);
295	  }
296	
297	  /**
298	   * Returns the {@link CallAdapter} for {@code returnType} from the available {@linkplain
299	   * #callAdapterFactories() factories} except {@code skipPast}.
300	   *
301	   * @throws IllegalArgumentException if no call adapter available for {@code type}.
302	   */
303	  public CallAdapter<?, ?> nextCallAdapter(
304	      @Nullable CallAdapter.Factory skipPast, Type returnType, Annotation[] annotations) {
305	    Objects.requireNonNull(returnType, "returnType == null");
306	    Objects.requireNonNull(annotations, "annotations == null");
307	
308	    int start = callAdapterFactories.indexOf(skipPast) + 1;
309	    for (int i = start, count = callAdapterFactories.size(); i < count; i++) {
310	      CallAdapter<?, ?> adapter = callAdapterFactories.get(i).get(returnType, annotations, this);
311	      if (adapter != null) {
312	        return adapter;
313	      }
314	    }
315	
316	    StringBuilder builder =
317	        new StringBuilder("Could not locate call adapter for ").append(returnType).append(".\n");
318	    if (skipPast != null) {
319	      builder.append("  Skipped:");
320	      for (int i = 0; i < start; i++) {
321	        builder.append("\n   * ").append(callAdapterFactories.get(i).getClass().getName());
322	      }
323	      builder.append('\n');
324	    }
325	    builder.append("  Tried:");
326	    for (int i = start, count = callAdapterFactories.size(); i < count; i++) {
327	      builder.append("\n   * ").append(callAdapterFactories.get(i).getClass().getName());
328	    }
329	    throw new IllegalArgumentException(builder.toString());
330	  }
