342	  /**
343	   * Returns a {@link Converter} for {@code type} to {@link RequestBody} from the available
344	   * {@linkplain #converterFactories() factories}.
345	   *
346	   * @throws IllegalArgumentException if no converter available for {@code type}.
347	   */
348	  public <T> Converter<T, RequestBody> requestBodyConverter(
349	      Type type, Annotation[] parameterAnnotations, Annotation[] methodAnnotations) {
350	    return nextRequestBodyConverter(null, type, parameterAnnotations, methodAnnotations);
351	  }
352	
353	  /**
354	   * Returns a {@link Converter} for {@code type} to {@link RequestBody} from the available
355	   * {@linkplain #converterFactories() factories} except {@code skipPast}.
356	   *
357	   * @throws IllegalArgumentException if no converter available for {@code type}.
358	   */
359	  public <T> Converter<T, RequestBody> nextRequestBodyConverter(
360	      @Nullable Converter.Factory skipPast,
361	      Type type,
362	      Annotation[] parameterAnnotations,
363	      Annotation[] methodAnnotations) {
364	    Objects.requireNonNull(type, "type == null");
365	    Objects.requireNonNull(parameterAnnotations, "parameterAnnotations == null");
366	    Objects.requireNonNull(methodAnnotations, "methodAnnotations == null");
367	
368	    int start = converterFactories.indexOf(skipPast) + 1;
369	    for (int i = start, count = converterFactories.size(); i < count; i++) {
370	      Converter.Factory factory = converterFactories.get(i);
371	      Converter<?, RequestBody> converter =
372	          factory.requestBodyConverter(type, parameterAnnotations, methodAnnotations, this);
373	      if (converter != null) {
374	        //noinspection unchecked
375	        return (Converter<T, RequestBody>) converter;
376	      }
377	    }
378	
379	    StringBuilder builder =
380	        new StringBuilder("Could not locate RequestBody converter for ").append(type).append(".\n");
381	    if (skipPast != null) {
382	      builder.append("  Skipped:");
383	      for (int i = 0; i < start; i++) {
384	        builder.append("\n   * ").append(converterFactories.get(i).getClass().getName());
385	      }
386	      builder.append('\n');
387	    }
388	    builder.append("  Tried:");
389	    for (int i = start, count = converterFactories.size(); i < count; i++) {
390	      builder.append("\n   * ").append(converterFactories.get(i).getClass().getName());
391	    }
392	    throw new IllegalArgumentException(builder.toString());
393	  }
394	
395	  /**
396	   * Returns a {@link Converter} for {@link ResponseBody} to {@code type} from the available
397	   * {@linkplain #converterFactories() factories}.
398	   *
399	   * @throws IllegalArgumentException if no converter available for {@code type}.
400	   */
401	  public <T> Converter<ResponseBody, T> responseBodyConverter(Type type, Annotation[] annotations) {
402	    return nextResponseBodyConverter(null, type, annotations);
403	  }
404	
405	  /**
406	   * Returns a {@link Converter} for {@link ResponseBody} to {@code type} from the available
407	   * {@linkplain #converterFactories() factories} except {@code skipPast}.
408	   *
409	   * @throws IllegalArgumentException if no converter available for {@code type}.
410	   */
411	  public <T> Converter<ResponseBody, T> nextResponseBodyConverter(
412	      @Nullable Converter.Factory skipPast, Type type, Annotation[] annotations) {
413	    Objects.requireNonNull(type, "type == null");
414	    Objects.requireNonNull(annotations, "annotations == null");
415	
416	    int start = converterFactories.indexOf(skipPast) + 1;
417	    for (int i = start, count = converterFactories.size(); i < count; i++) {
418	      Converter<ResponseBody, ?> converter =
419	          converterFactories.get(i).responseBodyConverter(type, annotations, this);
420	      if (converter != null) {
421	        //noinspection unchecked
422	        return (Converter<ResponseBody, T>) converter;
423	      }
424	    }
425	
426	    StringBuilder builder =
427	        new StringBuilder("Could not locate ResponseBody converter for ")
428	            .append(type)
429	            .append(".\n");
430	    if (skipPast != null) {
431	      builder.append("  Skipped:");
432	      for (int i = 0; i < start; i++) {
433	        builder.append("\n   * ").append(converterFactories.get(i).getClass().getName());
434	      }
435	      builder.append('\n');
436	    }
437	    builder.append("  Tried:");
438	    for (int i = start, count = converterFactories.size(); i < count; i++) {
439	      builder.append("\n   * ").append(converterFactories.get(i).getClass().getName());
440	    }
441	    throw new IllegalArgumentException(builder.toString());
442	  }
443	
444	  /**
445	   * Returns a {@link Converter} for {@code type} to {@link String} from the available {@linkplain
446	   * #converterFactories() factories}.
447	   */
448	  public <T> Converter<T, String> stringConverter(Type type, Annotation[] annotations) {
449	    Objects.requireNonNull(type, "type == null");
450	    Objects.requireNonNull(annotations, "annotations == null");
451	
452	    for (int i = 0, count = converterFactories.size(); i < count; i++) {
453	      Converter<?, String> converter =
454	          converterFactories.get(i).stringConverter(type, annotations, this);
455	      if (converter != null) {
