472	  }
473	
474	  public Builder newBuilder() {
475	    return new Builder(this);
476	  }
477	
478	  /**
479	   * Build a new {@link Retrofit}.
480	   *
481	   * <p>Calling {@link #baseUrl} is required before calling {@link #build()}. All other methods are
482	   * optional.
483	   */
484	  public static final class Builder {
485	    private @Nullable okhttp3.Call.Factory callFactory;
486	    private @Nullable HttpUrl baseUrl;
487	    private final List<Converter.Factory> converterFactories = new ArrayList<>();
488	    private final List<CallAdapter.Factory> callAdapterFactories = new ArrayList<>();
489	    private @Nullable Executor callbackExecutor;
490	    private boolean validateEagerly;
491	
492	    public Builder() {}
493	
494	    Builder(Retrofit retrofit) {
495	      callFactory = retrofit.callFactory;
496	      baseUrl = retrofit.baseUrl;
497	
498	      // Do not add the default BuiltIntConverters and platform-aware converters added by build().
499	      for (int i = 1,
500	              size = retrofit.converterFactories.size() - retrofit.defaultConverterFactoriesSize;
501	          i < size;
502	          i++) {
503	        converterFactories.add(retrofit.converterFactories.get(i));
504	      }
505	
506	      // Do not add the default, platform-aware call adapters added by build().
507	      for (int i = 0,
508	              size =
509	                  retrofit.callAdapterFactories.size() - retrofit.defaultCallAdapterFactoriesSize;
510	          i < size;
511	          i++) {
512	        callAdapterFactories.add(retrofit.callAdapterFactories.get(i));
513	      }
514	
515	      callbackExecutor = retrofit.callbackExecutor;
516	      validateEagerly = retrofit.validateEagerly;
517	    }
518	
519	    /**
520	     * The HTTP client used for requests.
521	     *
522	     * <p>This is a convenience method for calling {@link #callFactory}.
523	     */
524	    public Builder client(OkHttpClient client) {
525	      return callFactory(Objects.requireNonNull(client, "client == null"));
526	    }
527	
528	    /**
529	     * Specify a custom call factory for creating {@link Call} instances.
530	     *
531	     * <p>Note: Calling {@link #client} automatically sets this value.
532	     */
533	    public Builder callFactory(okhttp3.Call.Factory factory) {
534	      this.callFactory = Objects.requireNonNull(factory, "factory == null");
535	      return this;
536	    }
537	
538	    /**
539	     * Set the API base URL.
540	     *
541	     * @see #baseUrl(HttpUrl)
542	     */
543	    public Builder baseUrl(URL baseUrl) {
544	      Objects.requireNonNull(baseUrl, "baseUrl == null");
545	      return baseUrl(HttpUrl.get(baseUrl.toString()));
546	    }
547	
548	    /**
549	     * Set the API base URL.
550	     *
551	     * @see #baseUrl(HttpUrl)
552	     */
553	    public Builder baseUrl(String baseUrl) {
554	      Objects.requireNonNull(baseUrl, "baseUrl == null");
555	      return baseUrl(HttpUrl.get(baseUrl));
556	    }
557	
558	    /**
559	     * Set the API base URL.
560	     *
561	     * <p>The specified endpoint values (such as with {@link GET @GET}) are resolved against this
562	     * value using {@link HttpUrl#resolve(String)}. The behavior of this matches that of an {@code
563	     * <a href="">} link on a website resolving on the current URL.
564	     *
565	     * <p><b>Base URLs should always end in {@code /}.</b>
566	     *
567	     * <p>A trailing {@code /} ensures that endpoints values which are relative paths will correctly
568	     * append themselves to a base which has path components.
569	     *
570	     * <p><b>Correct:</b><br>
571	     * Base URL: http://example.com/api/<br>
572	     * Endpoint: foo/bar/<br>
573	     * Result: http://example.com/api/foo/bar/
574	     *
575	     * <p><b>Incorrect:</b><br>
576	     * Base URL: http://example.com/api<br>
577	     * Endpoint: foo/bar/<br>
578	     * Result: http://example.com/foo/bar/
579	     *
580	     * <p>This method enforces that {@code baseUrl} has a trailing {@code /}.
581	     *
582	     * <p><b>Endpoint values which contain a leading {@code /} are absolute.</b>
583	     *
584	     * <p>Absolute values retain only the host from {@code baseUrl} and ignore any specified path
585	     * components.
586	     *
587	     * <p>Base URL: http://example.com/api/<br>
588	     * Endpoint: /foo/bar/<br>
589	     * Result: http://example.com/foo/bar/
590	     *
591	     * <p>Base URL: http://example.com/<br>
592	     * Endpoint: /foo/bar/<br>
593	     * Result: http://example.com/foo/bar/
594	     *
595	     * <p><b>Endpoint values may be a full URL.</b>
596	     *
597	     * <p>Values which have a host replace the host of {@code baseUrl} and values also with a scheme
598	     * replace the scheme of {@code baseUrl}.
599	     *
600	     * <p>Base URL: http://example.com/<br>
601	     * Endpoint: https://github.com/lysine-dev/retrofit/<br>
602	     * Result: https://github.com/lysine-dev/retrofit/
603	     *
604	     * <p>Base URL: http://example.com<br>
605	     * Endpoint: //github.com/lysine-dev/retrofit/<br>
606	     * Result: http://github.com/lysine-dev/retrofit/ (note the scheme stays 'http')
607	     */
608	    public Builder baseUrl(HttpUrl baseUrl) {
609	      Objects.requireNonNull(baseUrl, "baseUrl == null");
610	      List<String> pathSegments = baseUrl.pathSegments();
611	      if (!"".equals(pathSegments.get(pathSegments.size() - 1))) {
612	        throw new IllegalArgumentException("baseUrl must end in /: " + baseUrl);
613	      }
614	      this.baseUrl = baseUrl;
615	      return this;
616	    }
617	
618	    /** Add converter factory for serialization and deserialization of objects. */
619	    public Builder addConverterFactory(Converter.Factory factory) {
620	      converterFactories.add(Objects.requireNonNull(factory, "factory == null"));
621	      return this;
622	    }
623	
624	    /**
625	     * Add a call adapter factory for supporting service method return types other than {@link
626	     * Call}.
627	     */
628	    public Builder addCallAdapterFactory(CallAdapter.Factory factory) {
629	      callAdapterFactories.add(Objects.requireNonNull(factory, "factory == null"));
630	      return this;
631	    }
632	
633	    /**
634	     * The executor on which {@link Callback} methods are invoked when returning {@link Call} from
635	     * your service method.
636	     *
637	     * <p>Note: {@code executor} is not used for {@linkplain #addCallAdapterFactory custom method
638	     * return types}.
639	     */
640	    public Builder callbackExecutor(Executor executor) {
641	      this.callbackExecutor = Objects.requireNonNull(executor, "executor == null");
642	      return this;
643	    }
644	
645	    /** Returns a modifiable list of call adapter factories. */
646	    public List<CallAdapter.Factory> callAdapterFactories() {
647	      return this.callAdapterFactories;
648	    }
649	
650	    /** Returns a modifiable list of converter factories. */
651	    public List<Converter.Factory> converterFactories() {
652	      return this.converterFactories;
653	    }
654	
655	    /**
656	     * When calling {@link #create} on the resulting {@link Retrofit} instance, eagerly validate the
657	     * configuration of all methods in the supplied interface.
658	     */
659	    public Builder validateEagerly(boolean validateEagerly) {
660	      this.validateEagerly = validateEagerly;
661	      return this;
662	    }
663	
664	    /**
665	     * Create the {@link Retrofit} instance using the configured values.
666	     *
667	     * <p>Note: If neither {@link #client} nor {@link #callFactory} is called a default {@link
668	     * OkHttpClient} will be created and used.
669	     */
670	    public Retrofit build() {
671	      if (baseUrl == null) {
672	        throw new IllegalStateException("Base URL required.");
673	      }
674	
675	      okhttp3.Call.Factory callFactory = this.callFactory;
676	      if (callFactory == null) {
677	        callFactory = new OkHttpClient();
678	      }
679	
680	      Executor callbackExecutor = this.callbackExecutor;
681	      if (callbackExecutor == null) {
682	        callbackExecutor = Platform.callbackExecutor;
683	      }
684	
685	      BuiltInFactories builtInFactories = Platform.builtInFactories;
686	
687	      // Make a defensive copy of the adapters and add the default Call adapter.
688	      List<CallAdapter.Factory> callAdapterFactories = new ArrayList<>(this.callAdapterFactories);
689	      List<? extends CallAdapter.Factory> defaultCallAdapterFactories =
690	          builtInFactories.createDefaultCallAdapterFactories(callbackExecutor);
691	      callAdapterFactories.addAll(defaultCallAdapterFactories);
692	
693	      // Make a defensive copy of the converters.
694	      List<? extends Converter.Factory> defaultConverterFactories =
695	          builtInFactories.createDefaultConverterFactories();
696	      int defaultConverterFactoriesSize = defaultConverterFactories.size();
697	      List<Converter.Factory> converterFactories =
698	          new ArrayList<>(1 + this.converterFactories.size() + defaultConverterFactoriesSize);
699	
700	      // Add the built-in converter factory first. This prevents overriding its behavior but also
701	      // ensures correct behavior when using converters that consume all types.
702	      converterFactories.add(new BuiltInConverters());
703	      converterFactories.addAll(this.converterFactories);
704	      converterFactories.addAll(defaultConverterFactories);
705	
706	      return new Retrofit(
707	          callFactory,
708	          baseUrl,
709	          unmodifiableList(converterFactories),
710	          defaultConverterFactoriesSize,
711	          unmodifiableList(callAdapterFactories),
712	          defaultCallAdapterFactories.size(),
713	          callbackExecutor,
714	          validateEagerly);
715	    }
716	  }
717	}
